// Meta verifies the webhook endpoint with a GET request that
// includes hub.verify_token. If it matches, we must echo back
// hub.challenge so Meta enables the subscription.
const query = $input.item.json.query ?? {};

const expectedToken = 'REPLACE_WITH_VERIFY_TOKEN';
const mode = query['hub.mode'];
const token = query['hub.verify_token'];
const challenge = query['hub.challenge'];

if (mode === 'subscribe' && token === expectedToken && challenge) {
  return { json: { status: 'verified', challenge } };
}

return {
  json: { status: 'rejected', reason: 'verify_token mismatch or missing challenge' },
};

// The WhatsApp Business Cloud API delivers messages as a deeply
// nested JSON payload. Here we flatten only the fields the bot
// needs: who wrote, what they wrote, and the event type.
const body = $input.item.json.body ?? {};
const change = body?.entry?.[0]?.changes?.[0] ?? {};
const value = change.value ?? {};
const contact = value.contacts?.[0] ?? {};
const message = value.messages?.[0];

return {
  json: {
    phone: message ? message.from : null,
    messageId: message ? message.id : null,
    name: contact.profile?.name ?? null,
    text: message?.text?.body ?? null,
    eventType: value.messages ? 'message' : value.statuses ? 'status' : 'unknown',
  },
};

// Business configuration. Replace the placeholders with your own
// values. utcOffsetMinutes is the business time zone offset in
// minutes (negative for west of UTC), e.g. El Salvador = -360.
//
// Concurrency: on confirm the workflow atomically reserves the slot
// in a PostgreSQL 'reservations' table (see README) before creating
// the calendar event. No new config values are needed for it — the
// table is created and pruned by the companion cleanup workflow
// (cleanup-workflow.json).
return {
  json: {
    businessName: 'REPLACE_WITH_BUSINESS_NAME',
    calendarId: 'REPLACE_WITH_CALENDAR_ID',
    phoneNumberId: 'REPLACE_WITH_PHONE_NUMBER_ID',
    openingHour: 9,
    closingHour: 18,
    slotMinutes: 30,
    utcOffsetMinutes: -360,
    services: [
      { id: 1, name: 'Consulta medica', duration: 30 },
      { id: 2, name: 'Asesoramiento', duration: 60 },
    ],
  },
};

// Keeps one conversation per phone number in workflow static
// data. 'menu' is the fallback step for any phone that has
// never written before, so a stale or unknown step is repaired
// automatically. Status events (delivered/read) and messages
// without text are routed to the 'ignore' step.
const state = $getWorkflowStaticData('global');
const item = $input.item.json;
const phone = item.phone;

if (item.eventType !== 'message' || !phone || !item.text) {
  return { json: { step: 'ignore', phone } };
}

const text = String(item.text).trim();
state[phone] = state[phone] ?? { step: 'menu', data: {} };
const session = state[phone];

const resets = ['menu', 'cancel', 'salir', 'reiniciar', '0'];
if (resets.includes(text.toLowerCase())) {
  session.step = 'menu';
  session.data = {};
}

return {
  json: {
    step: session.step,
    phone,
    name: item.name,
    text,
    data: session.data,
  },
};

// Shows the main menu. If the user already typed an option,
// advance directly instead of repeating the menu.
const state = $getWorkflowStaticData('global');
const session = state[$json.phone];
const cfg = $('Config').first().json;
const text = $json.text.toLowerCase();
const name = $json.name;

if (text === '1') {
  session.step = 'service';
  const lines = cfg.services.map((s) => `${s.id}. ${s.name}`);
  return {
    json: {
      phone: $json.phone,
      reply: [
        `Perfecto${name ? ', ' + name : ''}. Que servicio desea reservar?`,
        lines.join('\n'),
        'Responda con el numero de la opcion.',
      ].join('\n\n'),
    },
  };
}

if (text === '0') {
  session.step = 'menu';
  session.data = {};
  return {
    json: {
      phone: $json.phone,
      reply: 'Gracias por escribirnos. Hasta pronto!',
    },
    };
}

// Keep the conversation on the 'menu' step until the user picks
// "Reservar" (1) or "Salir" (0), so a greeting + '1' is not
// misread as a service choice.
return {
    json: {
      phone: $json.phone,
      reply: [
      `Hola${name ? ' ' + name : ''}, bienvenido/a a ${cfg.businessName}.`,
      'Que desea hacer?',
      '1. Reservar una cita',
      '0. Salir',
      'Responda con el numero de la opcion.',
    ].join('\n'),
  },
};

// Reads the chosen service. Valid options advance to the date
// step; anything else re-asks with the list of services.
const state = $getWorkflowStaticData('global');
const session = state[$json.phone];
const cfg = $('Config').first().json;
const choice = parseInt($json.text, 10);
const service = cfg.services.find((s) => s.id === choice);

if (!service) {
  const lines = cfg.services.map((s) => `${s.id}. ${s.name}`);
  return {
    json: {
      phone: $json.phone,
      reply: [
        'No reconoci esa opcion. Elija uno de los servicios disponibles:',
        lines.join('\n'),
        'Responda con el numero de la opcion.',
      ].join('\n\n'),
    },
  };
}

session.data.service = service;
session.step = 'date';
return {
  json: {
    phone: $json.phone,
    reply: 'Para que fecha desea la cita? (formato DD/MM/AAAA, por ejemplo 25/12/2026)',
  },
};

// Parses DD/MM/YYYY and computes the day window in UTC using the
// business time zone offset. Invalid dates produce a re-ask reply
// (status 'invalid') that skips the calendar call.
const state = $getWorkflowStaticData('global');
const session = state[$json.phone];
const cfg = $('Config').first().json;
const text = $json.text.trim();
const match = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(text);

if (!match) {
  return {
    json: {
      phone: $json.phone,
      status: 'invalid',
      reply: 'No entendi la fecha. Use el formato DD/MM/AAAA, por ejemplo 25/12/2026.',
    },
  };
}

const [, dd, mm, yyyy] = match;
const dateKey = `${yyyy}-${mm}-${dd}`;
const dayStartUtc = new Date(
  Date.parse(`${dateKey}T00:00:00Z`) - cfg.utcOffsetMinutes * 60000,
).toISOString();
const dayEndUtc = new Date(
  Date.parse(`${dateKey}T00:00:00Z`) - cfg.utcOffsetMinutes * 60000 + 24 * 3600 * 1000,
).toISOString();
const durationMinutes = session.data.service?.duration ?? cfg.slotMinutes;

session.data.dateKey = dateKey;
session.data.serviceId = session.data.service?.id;

return {
  json: {
    phone: $json.phone,
    status: 'ok',
    dateKey,
    dayStart: dayStartUtc,
    dayEnd: dayEndUtc,
    durationMinutes,
  },
};

// Computes the free time slots for the day by removing the busy
// ranges returned by the Availability node. Slot length comes
// from the chosen service duration. All math runs in UTC using
// the business offset from the Config node.
//
// The day context (phone/dateKey/duration) is read from whichever
// upstream node produced it: Handle Date on the normal path, or
// Re-offer Slots after a lost reservation. The Availability node
// only outputs the busy ranges, so it cannot carry this context
// and $json only ever holds a busy-slot item here.
const cfg = $('Config').first().json;
const date = $('Handle Date').isExecuted
  ? $('Handle Date').first().json
  : $('Re-offer Slots').first().json;
const phone = date.phone;
const durationMinutes = date.durationMinutes ?? cfg.slotMinutes;

const busy = $input
  .all()
  .map((item) =>
    item.json.start
      ? { start: Date.parse(item.json.start), end: Date.parse(item.json.end) }
      : null,
  )
  .filter((item) => item !== null);

const dayStart = Date.parse(`${date.dateKey}T00:00:00Z`) - cfg.utcOffsetMinutes * 60000;
const slotMs = durationMinutes * 60000;
const slots = [];

for (
  let start = dayStart + cfg.openingHour * 3600000;
  start + slotMs <= dayStart + cfg.closingHour * 3600000;
  start += slotMs
) {
  const end = start + slotMs;
  const clashes = busy.some((b) => start < b.end && end > b.start);
  if (!clashes) {
    slots.push({
      start: new Date(start).toISOString(),
      end: new Date(end).toISOString(),
    });
  }
}

return {
  json: {
    phone,
    dateKey: date.dateKey,
    slots,
    slotsCount: slots.length,
  },
};

// Lists the free slots and stores them in the conversation state
// so the time step can validate the user's choice against them.
const state = $getWorkflowStaticData('global');
const session = state[$json.phone];
const cfg = $('Config').first().json;

const formatLocal = (iso) =>
  new Date(Date.parse(iso) + cfg.utcOffsetMinutes * 60000).toISOString().slice(11, 16);

session.data.slots = $json.slots;
session.step = 'time';

const lines = $json.slots.map((slot, i) => `${i + 1}. ${formatLocal(slot.start)} hs`);

return {
  json: {
    phone: $json.phone,
    reply: [
      `Horarios disponibles para el ${$json.dateKey}:`,
      lines.join('\n'),
      'Responda con el numero del horario que prefiera.',
    ].join('\n\n'),
  },
};

// No free slot for the chosen day: go back to the date step.
const state = $getWorkflowStaticData('global');
state[$json.phone].step = 'date';

return {
  json: {
    phone: $json.phone,
    reply: `No quedan horarios disponibles para el ${$json.dateKey}. Elija otra fecha (DD/MM/AAAA).`,
  },
};

// Validates the chosen slot number against the list shown in the
// previous message, then moves to the name step.
const state = $getWorkflowStaticData('global');
const session = state[$json.phone];
const cfg = $('Config').first().json;
const slots = session.data.slots ?? [];
const choice = parseInt($json.text, 10);

const formatLocal = (iso) =>
  new Date(Date.parse(iso) + cfg.utcOffsetMinutes * 60000).toISOString().slice(11, 16);

if (!Number.isInteger(choice) || choice < 1 || choice > slots.length) {
  const lines = slots.map((slot, i) => `${i + 1}. ${formatLocal(slot.start)} hs`);
  return {
    json: {
      phone: $json.phone,
      reply: ['No reconoci esa opcion. Elija un horario de la lista:', lines.join('\n')].join('\n\n'),
    },
  };
}

session.data.time = slots[choice - 1];
session.step = 'name';
return {
  json: {
    phone: $json.phone,
    reply: 'Perfecto. Cual es su nombre completo?',
  },
};

// Stores the customer name and shows the confirmation summary.
const state = $getWorkflowStaticData('global');
const session = state[$json.phone];
const cfg = $('Config').first().json;
const name = $json.text.trim();

if (!name || name.length < 2) {
  return {
    json: {
      phone: $json.phone,
      reply: 'Por favor escriba su nombre completo.',
    },
  };
}

session.data.name = name;
session.step = 'confirm';

const formatLocal = (iso) =>
  new Date(Date.parse(iso) + cfg.utcOffsetMinutes * 60000).toISOString().slice(11, 16);
const slot = session.data.time ?? {};
const serviceName = session.data.service?.name ?? '';

return {
  json: {
    phone: $json.phone,
    reply: [
      'Confirme los datos de su cita:',
      `Servicio: ${serviceName}`,
      `Fecha: ${session.data.dateKey}`,
      `Horario: ${formatLocal(slot.start)} hs`,
      `Nombre: ${name}`,
      '',
      'Responda 1 para confirmar o 2 para cancelar.',
    ].join('\n'),
  },
};

// 1 = confirm, 2 = cancel. Anything else re-asks. The confirmed
// item carries every field the calendar node needs.
const state = $getWorkflowStaticData('global');
const session = state[$json.phone];
const cfg = $('Config').first().json;
const text = $json.text.trim();

const formatLocal = (iso) =>
  new Date(Date.parse(iso) + cfg.utcOffsetMinutes * 60000).toISOString().slice(11, 16);
const slot = session.data.time ?? {};

if (text === '1') {
  return {
    json: {
      phone: $json.phone,
      status: 'confirmed',
      start: slot.start,
      end: slot.end,
      serviceName: session.data.service?.name ?? '',
      dateKey: session.data.dateKey ?? '',
      name: session.data.name ?? '',
    },
  };
}

if (text === '2') {
  session.step = 'menu';
  session.data = {};
  return {
    json: {
      phone: $json.phone,
      status: 'cancelled',
      reply: 'Cita cancelada. Envie 1 cuando quiera reservar nuevamente.',
    },
  };
}

return {
  json: {
    phone: $json.phone,
    status: 'invalid',
    reply: 'Por favor responda 1 para confirmar o 2 para cancelar.',
  },
};

// Calendar create failed even though the slot was atomically
// reserved. The reservation was already rolled back by the
// Release Reservation node, so tell the customer to retry.
const input = $('Handle Confirm').first().json;

return {
  json: {
    phone: input.phone,
    reply: [
      'Lo sentimos, no pudimos confirmar su cita.',
      'Hubo un error al reservar su horario.',
      'Por favor intentelo de nuevo en unos minutos.',
    ].join('\n'),
  },
};

// The chosen slot was already taken by someone else. Tells the
// customer and re-lists the free slots by re-entering the existing
// day-availability chain (Re-offer Slots -> Check Day Availability
// -> Compute Free Slots -> Show Slots).
const input = $('Handle Confirm').first().json;
const cfg = $('Config').first().json;

const formatLocal = (iso) =>
  new Date(Date.parse(iso) + cfg.utcOffsetMinutes * 60000).toISOString().slice(11, 16);

const state = $getWorkflowStaticData('global');
const session = state[input.phone];

// The day window and service duration never reached the session
// state (Handle Date only carries them on its output item), so
// recompute them here exactly like Handle Date does.
const dayStart = new Date(
  Date.parse(`${input.dateKey}T00:00:00Z`) - cfg.utcOffsetMinutes * 60000,
).toISOString();
const dayEnd = new Date(
  Date.parse(`${input.dateKey}T00:00:00Z`) - cfg.utcOffsetMinutes * 60000 + 24 * 3600 * 1000,
).toISOString();
const durationMinutes = session.data.service?.duration ?? cfg.slotMinutes;

// Preview of the previously listed slots (minus the one just taken);
// the authoritative fresh list is sent by Show Slots right after.
const next = (session.data.slots ?? []).filter((s) => s.start !== input.start);
const lines = next.map((slot) => formatLocal(slot.start)).slice(0, 3);
const alt = lines.length
  ? ['Alternativas disponibles:', ...lines.map((t) => `- ${t}`)].join('\n')
  : 'No quedan mas horarios disponibles para esa fecha.';

return {
  json: {
    phone: input.phone,
    dateKey: input.dateKey,
    dayStart,
    dayEnd,
    durationMinutes,
    reply: [
      'Ese horario acaba de ser reservado por otra persona.',
      alt,
      'Responda con el numero del horario que prefiera.',
    ].join('\n'),
  },
};

// Builds the confirmation message after the calendar event was
// created, then resets the conversation to the menu.
const input = $('Handle Confirm').first().json;
const cfg = $('Config').first().json;

const formatLocal = (iso) =>
  new Date(Date.parse(iso) + cfg.utcOffsetMinutes * 60000).toISOString().slice(11, 16);

const state = $getWorkflowStaticData('global');
state[input.phone].step = 'menu';
state[input.phone].data = {};

return {
  json: {
    phone: input.phone,
    reply: [
      'Su cita fue confirmada.',
      `Servicio: ${input.serviceName}`,
      `Fecha: ${input.dateKey}`,
      `Horario: ${formatLocal(input.start)} hs`,
      'Nos vemos pronto!',
    ].join('\n'),
  },
};
